from collections import deque

def isEvenOddTree(root):
    queue = deque([root])
    level = 0
    while queue:
        size = len(queue)
        prev = None
        for _ in range(size):
            node = queue.popleft()
            val = node.val
            # Check parity
            if level % 2 == 0:
                if val % 2 == 0 or (prev is not None and val <= prev):
                    return False
            else:
                if val % 2 == 1 or (prev is not None and val >= prev):
                    return False
            prev = val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        level += 1
    return True
